def extract(tree):
    rows = tree.where(content_desc="statusLabel")
    if not rows:
        raise ValueError("Translation status label is absent")
    status = rows[0]["text"].lower()
    return not ("translation failed" in status or "needs a download" in status)

def extract(tree):
    rows = tree.where(content_desc="statusLabel")
    if not rows:
        raise ValueError("Translation status label is absent")
    return "success" in rows[0]["text"].lower()

def extract(tree):
    rows = tree.where(content_desc="statusLabel")
    if not rows:
        raise ValueError("The visible status message is absent")
    return rows[0]["text"]
